def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the full boundary line of color 2.
    vertical = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    horizontal = [r for r in range(h) if all(grid[r][c] == 2 for c in range(w))]

    # The background is the most common color other than the boundary color.
    counts = {}
    for row in grid:
        for value in row:
            if value != 2:
                counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, background)]
    if not obj:
        return [row[:] for row in grid]

    out = [row[:] for row in grid]

    if vertical:
        wall = vertical[0]
        min_c = min(c for _, c in obj)
        max_c = max(c for _, c in obj)
        if wall > w // 2:  # Boundary on the right
            shift = wall - 1 - max_c
            divider = min_c + shift - 1
        else:  # Boundary on the left
            shift = wall + 1 - min_c
            divider = max_c + shift + 1

        for r in range(h):
            for c in range(w):
                if out[r][c] not in (2,):
                    out[r][c] = background
        for r, c in obj:
            out[r][c + shift] = grid[r][c]
        if 0 <= divider < w:
            for r in range(h):
                if out[r][divider] != 2:
                    out[r][divider] = 8

    elif horizontal:
        wall = horizontal[0]
        min_r = min(r for r, _ in obj)
        max_r = max(r for r, _ in obj)
        if wall > h // 2:  # Boundary at the bottom
            shift = wall - 1 - max_r
            divider = min_r + shift - 1
        else:  # Boundary at the top
            shift = wall + 1 - min_r
            divider = max_r + shift + 1

        for r in range(h):
            for c in range(w):
                if out[r][c] != 2:
                    out[r][c] = background
        for r, c in obj:
            out[r + shift][c] = grid[r][c]
        if 0 <= divider < h:
            for c in range(w):
                if out[divider][c] != 2:
                    out[divider][c] = 8

    return out
